6	// Fill kernel — scalar broadcast fill to output tensor
7	
8	#include "kernel_operator.h"
9	
10	constexpr int32_t BUFFER_NUM = 2;
11	
12	template <typename T>
13	static __aicore__ void FillNative(GM_ADDR output,
14	                                   int64_t formerNum, int64_t formerLength,
15	                                   int64_t tailLength, int64_t tileLength,
16	                                   T val)
17	{
18	    AscendC::TPipe pipe;
19	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> q;
20	    AscendC::GlobalTensor<T> gm;
21	
22	    int64_t blk = AscendC::GetBlockIdx();
23	    int64_t len;
24	    if (blk < formerNum) { len = formerLength; gm.SetGlobalBuffer((__gm__ T *)output + formerLength * blk, len); }
25	    else { len = tailLength; int64_t ti = blk - formerNum; gm.SetGlobalBuffer((__gm__ T *)output + formerLength * formerNum + tailLength * ti, len); }
26	
27	    pipe.InitBuffer(q, BUFFER_NUM, tileLength * sizeof(T));
28	
29	    int64_t tn = (len + tileLength - 1) / tileLength;
30	    int64_t tt = len - (tn - 1) * tileLength;
31	    int64_t an = 32 / (int64_t)sizeof(T);
32	    int64_t at = ((tt + an - 1) / an) * an;
33	
34	    for (int64_t i = 0; i < tn - 1; ++i) {
35	        AscendC::LocalTensor<T> ol = q.AllocTensor<T>();
36	        AscendC::Duplicate(ol, val, tileLength);
37	        q.EnQue<T>(ol);
38	        AscendC::LocalTensor<T> o2 = q.DeQue<T>();
39	        AscendC::DataCopyExtParams cp {1, (uint32_t)(tileLength * sizeof(T)), 0, 0, 0};
40	        AscendC::DataCopyPad(gm[i * tileLength], o2, cp);
41	        q.FreeTensor(o2);
42	    }
43	    if (tn > 0) {
44	        AscendC::LocalTensor<T> ol = q.AllocTensor<T>();
45	        AscendC::Duplicate(ol, val, at);
46	        q.EnQue<T>(ol);
47	        AscendC::LocalTensor<T> o2 = q.DeQue<T>();
48	        AscendC::DataCopyExtParams cp {1, (uint32_t)(tt * sizeof(T)), 0, 0, 0};
49	        AscendC::DataCopyPad(gm[(tn - 1) * tileLength], o2, cp);
50	        q.FreeTensor(o2);
51	    }
52	}
53	
54	static __aicore__ void Fill8(GM_ADDR output,
55	                              int64_t formerNum, int64_t formerLength,
56	                              int64_t tailLength, int64_t tileLength,
57	                              int16_t packed)
58	{
59	    AscendC::TPipe pipe;
60	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> q;
61	    AscendC::GlobalTensor<int16_t> gm;
62	
63	    int64_t blk = AscendC::GetBlockIdx();
64	    int64_t len;
65	    __gm__ int16_t *gm16 = (__gm__ int16_t *)output;
66	    if (blk < formerNum) { len = formerLength; gm.SetGlobalBuffer(gm16 + (formerLength * blk) / 2, (len + 1) / 2); }
67	    else { len = tailLength; int64_t ti = blk - formerNum; int64_t bo = formerLength * formerNum + tailLength * ti; gm.SetGlobalBuffer(gm16 + bo / 2, (len + 1) / 2); }
68	
69	    int64_t cap = ((tileLength + 33) / 32) * 16;
70	    pipe.InitBuffer(q, BUFFER_NUM, cap * sizeof(int16_t));
71	
72	    int64_t tn = (len + tileLength - 1) / tileLength;
73	    int64_t tt = len - (tn - 1) * tileLength;
74	    int64_t at = ((tt + 31) / 32) * 32;
75	
76	    for (int64_t i = 0; i < tn - 1; ++i) {
77	        AscendC::LocalTensor<int16_t> ol = q.AllocTensor<int16_t>();
78	        AscendC::Duplicate(ol, packed, (tileLength + 1) / 2);
79	        q.EnQue<int16_t>(ol);
80	        AscendC::LocalTensor<int16_t> o2 = q.DeQue<int16_t>();
81	        AscendC::DataCopyExtParams cp {1, (uint32_t)tileLength, 0, 0, 0};
82	        AscendC::DataCopyPad(gm[(i * tileLength) / 2], o2, cp);
83	        q.FreeTensor(o2);
84	    }
85	    if (tn > 0) {
86	        AscendC::LocalTensor<int16_t> ol = q.AllocTensor<int16_t>();
87	        AscendC::Duplicate(ol, packed, (at + 1) / 2);
88	        q.EnQue<int16_t>(ol);
89	        AscendC::LocalTensor<int16_t> o2 = q.DeQue<int16_t>();
90	        AscendC::DataCopyExtParams cp {1, (uint32_t)tt, 0, 0, 0};
91	        AscendC::DataCopyPad(gm[((tn - 1) * tileLength) / 2], o2, cp);
92	        q.FreeTensor(o2);
93	    }
94	}
95	
96	static __aicore__ void Fill64(GM_ADDR output,
97	                               int64_t formerNum, int64_t formerLength,
98	                               int64_t tailLength, int64_t tileLength,
99	                               int32_t lo, int32_t hi)
100	{
101	    AscendC::TPipe pipe;
102	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> q;
103	    AscendC::TBuf<AscendC::TPosition::VECCALC> buf;
104	    AscendC::GlobalTensor<int32_t> gm;
105	
106	    int64_t blk = AscendC::GetBlockIdx();
107	    int64_t len;
108	    __gm__ int32_t *gm32 = (__gm__ int32_t *)output;
109	    if (blk < formerNum) { len = formerLength; gm.SetGlobalBuffer(gm32 + formerLength * blk * 2, len * 2); }
110	    else { len = tailLength; int64_t ti = blk - formerNum; int64_t bo = (formerLength * formerNum + tailLength * ti) * 8; gm.SetGlobalBuffer(gm32 + bo / 4, len * 2); }
111	
112	    int64_t cap = tileLength * 2;
113	    pipe.InitBuffer(buf, cap * sizeof(int32_t));
114	    pipe.InitBuffer(q, BUFFER_NUM, cap * sizeof(int32_t));
115	
116	    int64_t tn = (len + tileLength - 1) / tileLength;
117	    int64_t tt = len - (tn - 1) * tileLength;
118	    int64_t at = ((tt + 7) / 8) * 8;
119	
120	    for (int64_t i = 0; i < tn - 1; ++i) {
121	        int64_t n = tileLength * 2;
122	        AscendC::LocalTensor<int32_t> calc = buf.Get<int32_t>();
123	        AscendC::Duplicate(calc, lo, n);
124	        if (lo != hi) {
125	            int64_t r = tileLength, o = 0;
126	            while (r > 0) { uint8_t b = (uint8_t)(r < 255 ? r : 255); AscendC::Duplicate(calc[o * 2 + 1], hi, 1, b, 2, 2); o += b; r -= b; }
127	        }
128	        AscendC::LocalTensor<int32_t> ol = q.AllocTensor<int32_t>();
129	        AscendC::DataCopy(ol, calc, n);
130	        q.EnQue<int32_t>(ol);
131	        AscendC::LocalTensor<int32_t> o2 = q.DeQue<int32_t>();
132	        AscendC::DataCopyExtParams cp {1, (uint32_t)(tileLength * 8), 0, 0, 0};
133	        AscendC::DataCopyPad(gm[i * tileLength * 2], o2, cp);
134	        q.FreeTensor(o2);
135	    }
136	    if (tn > 0) {
137	        int64_t n = at * 2;
138	        AscendC::LocalTensor<int32_t> calc = buf.Get<int32_t>();
139	        AscendC::Duplicate(calc, lo, n);
140	        if (lo != hi) {
141	            int64_t r = at, o = 0;
142	            while (r > 0) { uint8_t b = (uint8_t)(r < 255 ? r : 255); AscendC::Duplicate(calc[o * 2 + 1], hi, 1, b, 2, 2); o += b; r -= b; }
143	        }
144	        AscendC::LocalTensor<int32_t> ol = q.AllocTensor<int32_t>();
145	        AscendC::DataCopy(ol, calc, n);
146	        q.EnQue<int32_t>(ol);
147	        AscendC::LocalTensor<int32_t> o2 = q.DeQue<int32_t>();
148	        AscendC::DataCopyExtParams cp {1, (uint32_t)(tt * 8), 0, 0, 0};
149	        AscendC::DataCopyPad(gm[(tn - 1) * tileLength * 2], o2, cp);
150	        q.FreeTensor(o2);
151	    }
152	}
153	
154	extern "C" __global__ __aicore__ void fill(
155	    GM_ADDR output,
156	    int64_t formerNum, int64_t formerLength,
157	    int64_t tailLength, int64_t tileLength,
158	    float scalarFloat, int64_t scalarInt, int64_t dtypeFlag)
159	{
160	    if (dtypeFlag == 0) {
161	        FillNative<half>(output, formerNum, formerLength, tailLength, tileLength, (half)scalarFloat);
162	    } else if (dtypeFlag == 1) {
163	        FillNative<float>(output, formerNum, formerLength, tailLength, tileLength, scalarFloat);
164	    } else if (dtypeFlag == 2) {
165	        uint32_t u = *(uint32_t *)&scalarFloat;
166	        FillNative<int16_t>(output, formerNum, formerLength, tailLength, tileLength, (int16_t)((u >> 16) & 0xFFFF));
167	    } else if (dtypeFlag == 3) {
168	        uint8_t u8 = (uint8_t)(int8_t)scalarInt;
169	        Fill8(output, formerNum, formerLength, tailLength, tileLength, (int16_t)(((uint16_t)u8 << 8) | u8));
170	    } else if (dtypeFlag == 4) {
171	        FillNative<int32_t>(output, formerNum, formerLength, tailLength, tileLength, (int32_t)scalarInt);
172	    } else if (dtypeFlag == 5) {
173	        int32_t lo = (int32_t)(scalarInt & 0xFFFFFFFFULL);
174	        int32_t hi = (int32_t)(((uint64_t)scalarInt >> 32) & 0xFFFFFFFFULL);
175	        Fill64(output, formerNum, formerLength, tailLength, tileLength, lo, hi);
176	    } else if (dtypeFlag == 6) {
177	        Fill8(output, formerNum, formerLength, tailLength, tileLength, scalarInt ? 0x0101 : 0);
178	    }
179	}
