11	// Fill op_host — tiling calculation + EXEC_KERNEL_CMD launch
12	// Scalar broadcast fill: output[i] = scalarValue for all i
13	
14	#include <algorithm>
15	#include <cstdint>
16	
17	#include <torch/extension.h>
18	#include <torch/library.h>
19	
20	#include "torch_kernel_helper.h"
21	#include "tiling/platform/platform_ascendc.h"
22	
23	#include "aclrtlaunch_fill.h"
24	
25	namespace ascend_kernel {
26	
27	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
28	
29	at::Tensor fill(at::IntArrayRef dims, const at::Tensor &value)
30	{
31	    // ---- 输入校验 ----
32	    TORCH_CHECK(value.dim() == 0, "fill: value must be a 0-dim scalar tensor, got ", value.dim(), " dims");
33	    TORCH_CHECK(
34	        value.scalar_type() == at::kFloat || value.scalar_type() == at::kHalf ||
35	            value.scalar_type() == at::kBFloat16 || value.scalar_type() == at::kChar ||
36	            value.scalar_type() == at::kInt || value.scalar_type() == at::kBool,
37	        "fill: supported dtypes: float32, float16, bfloat16, int8, int32, bool; "
38	        "int64 not supported; got ", value.scalar_type());
39	
40	    auto dimsVec = dims.vec();
41	    int64_t totalLength = 1;
42	    for (size_t i = 0; i < dimsVec.size(); ++i) {
43	        totalLength *= dimsVec[i];
44	    }
45	
46	    // ---- 创建输出张量 ----
47	    at::Tensor output = at::empty(dimsVec, value.options());
48	
49	    if (totalLength == 0) {
50	        return output;
51	    }
52	
53	    int64_t dtypeSize = value.element_size();
54	    auto scalarType = value.scalar_type();
55	
56	    // ---- dtypeFlag 映射 ----
57	    // 0=float16, 1=float32, 2=bfloat16, 3=int8, 4=int32, 5=int64, 6=bool
58	    int64_t dtypeFlag = 0;
59	    float scalarFloat = 0.0f;
60	    int64_t scalarInt = 0;
61	
62	    if (scalarType == at::kHalf) {
63	        dtypeFlag = 0;
64	        scalarFloat = static_cast<float>(value.item<at::Half>());
65	    } else if (scalarType == at::kFloat) {
66	        dtypeFlag = 1;
67	        scalarFloat = value.item<float>();
68	    } else if (scalarType == at::kBFloat16) {
69	        dtypeFlag = 2;
70	        scalarFloat = static_cast<float>(value.item<at::BFloat16>());
71	    } else if (scalarType == at::kChar) {
72	        dtypeFlag = 3;
73	        scalarInt = static_cast<int64_t>(value.item<int8_t>());
74	    } else if (scalarType == at::kInt) {
75	        dtypeFlag = 4;
76	        scalarInt = static_cast<int64_t>(value.item<int32_t>());
77	    } else if (scalarType == at::kLong) {
78	        dtypeFlag = 5;
79	        scalarInt = value.item<int64_t>();
80	    } else if (scalarType == at::kBool) {
81	        dtypeFlag = 6;
82	        scalarInt = value.item<bool>() ? 1 : 0;
83	    }
84	
85	    // ---- 获取硬件参数 ----
86	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
87	    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
88	    uint64_t ubSize;
89	    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
90	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
91	
92	    // ---- Effective dtype size (kernel may use wider internal types) ----
93	    int64_t effectiveDtypeSize = dtypeSize;
94	    if (dtypeFlag == 3 || dtypeFlag == 6) {
95	        effectiveDtypeSize = 2;  // int8/bool: kernel uses int16_t
96	    } else if (dtypeFlag == 5) {
97	        effectiveDtypeSize = 4;  // int64: kernel uses int32_t (with TBuf)
98	    }
99	    // int64 uses TBuf + TQue(2x) = 3 buffers of int32_t; coefficient = 3 * 4 = 12
100	    int64_t bufferCoefficient;
101	    if (dtypeFlag == 5) {
102	        bufferCoefficient = 3 * effectiveDtypeSize; // 12 for int64
103	    } else {
104	        bufferCoefficient = 3 * effectiveDtypeSize; // fp16/bf16: 6, fp32/int32: 12, int8: 6
105	    }
106	    // ---- Block 级 tiling (核间切分, Cache Line 512B 对齐) ----
107	    // Use byte-level alignment, then convert to elements
108	    int64_t totalLenBytes = totalLength * dtypeSize;
109	    int64_t coreNumClamped = coreNum < 1 ? 1 : coreNum;
110	    int64_t bytesPerCore = (totalLenBytes + coreNumClamped - 1) / coreNumClamped;
111	    int64_t bytesPerCoreAligned = ((bytesPerCore + CACHE_LINE_BYTE_LENGTH - 1) / CACHE_LINE_BYTE_LENGTH) * CACHE_LINE_BYTE_LENGTH;
112	
113	    int64_t usedCoreNum = (totalLenBytes + bytesPerCoreAligned - 1) / bytesPerCoreAligned;
114	    if (usedCoreNum < 1) { usedCoreNum = 1; }
115	    int64_t formerNum = usedCoreNum - 1;
116	    int64_t formerLength = bytesPerCoreAligned / dtypeSize;
117	    int64_t tailLengthBytes = totalLenBytes - (usedCoreNum - 1) * bytesPerCoreAligned;
118	    int64_t tailLength = tailLengthBytes / dtypeSize;
119	
120	    // ---- UB 级 tiling (核内切分) ----
121	    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
122	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
123	    // alignElements: ensure 32B in UB for the internal type; use the larger of 32/dtypeSize and 32/effectiveDtypeSize
124	    int64_t alignElements = 32 / dtypeSize;
125	    int64_t alignElementsEff = 32 / effectiveDtypeSize;
126	    if (alignElementsEff > alignElements) { alignElements = alignElementsEff; }
127	    if (alignElements < 1) { alignElements = 1; }
128	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
129	
130	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
131	
132	    // All params must be left-values for EXEC_KERNEL_CMD
133	    EXEC_KERNEL_CMD(fill, blockDim,
134	                    output,
135	                    formerNum, formerLength, tailLength, tileLength,
136	                    scalarFloat, scalarInt, dtypeFlag);
137	
138	    return output;
139	}
140	
141	}  // namespace ascend_kernel
