97	                               int64_t formerNum, int64_t formerLength,
98	                               int64_t tailLength, int64_t tileLength,
99	                               int32_t lo, int32_t hi)
100	{
101	    AscendC::TPipe pipe;
102	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> q;
103	    AscendC::TBuf<AscendC::TPosition::VECCALC> buf;
104	    AscendC::GlobalTensor<int32_t> gm;
105	
106	    int64_t blk = AscendC::GetBlockIdx();
107	    int64_t len;
108	    __gm__ int32_t *gm32 = (__gm__ int32_t *)output;
109	    if (blk < formerNum) { len = formerLength; gm.SetGlobalBuffer(gm32 + formerLength * blk * 2, len * 2); }
110	    else { len = tailLength; int64_t ti = blk - formerNum; int64_t bo = (formerLength * formerNum + tailLength * ti) * 8; gm.SetGlobalBuffer(gm32 + bo / 4, len * 2); }
111	
112	    int64_t cap = tileLength * 2;
113	    pipe.InitBuffer(buf, cap * sizeof(int32_t));
114	    pipe.InitBuffer(q, BUFFER_NUM, cap * sizeof(int32_t));
115	
116	    int64_t tn = (len + tileLength - 1) / tileLength;
117	    int64_t tt = len - (tn - 1) * tileLength;
118	    int64_t at = ((tt + 7) / 8) * 8;
119	
120	    for (int64_t i = 0; i < tn - 1; ++i) {
121	        int64_t n = tileLength * 2;
122	        AscendC::LocalTensor<int32_t> calc = buf.Get<int32_t>();
123	        AscendC::Duplicate(calc, lo, n);
124	        if (lo != hi) {
125	            int64_t r = tileLength, o = 0;
126	            while (r > 0) { uint8_t b = (uint8_t)(r < 255 ? r : 255); AscendC::Duplicate(calc[o * 2 + 1], hi, 1, b, 2, 2); o += b; r -= b; }
127	        }
