131	        AscendC::LocalTensor<int32_t> o2 = q.DeQue<int32_t>();
132	        AscendC::DataCopyExtParams cp {1, (uint32_t)(tileLength * 8), 0, 0, 0};
133	        AscendC::DataCopyPad(gm[i * tileLength * 2], o2, cp);
134	        q.FreeTensor(o2);
135	    }
