11	// Fill op_host — tiling calculation + EXEC_KERNEL_CMD launch
12	// Scalar broadcast fill: output[i] = scalarValue for all i
13	
14	#include <algorithm>
15	#include <cstdint>
16	
17	#include <torch/extension.h>
18	#include <torch/library.h>
19	
20	#include "torch_kernel_helper.h"
21	#include "tiling/platform/platform_ascendc.h"
22	
23	#include "aclrtlaunch_fill.h"
24	
25	namespace ascend_kernel {
26	
27	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
28	
29	at::Tensor fill(at::IntArrayRef dims, const at::Tensor &value)
30	{
31	    // ---- 输入校验 ----
32	    TORCH_CHECK(value.dim() == 0, "fill: value must be a 0-dim scalar tensor, got ", value.dim(), " dims");
33	    TORCH_CHECK(
34	        value.scalar_type() == at::kFloat || value.scalar_type() == at::kHalf ||
35	            value.scalar_type() == at::kBFloat16 || value.scalar_type() == at::kChar ||
36	            value.scalar_type() == at::kInt || value.scalar_type() == at::kLong ||
37	            value.scalar_type() == at::kBool,
38	        "fill: supported dtypes: float32, float16, bfloat16, int8, int32, int64, bool; got ",
39	        value.scalar_type());
40	
41	    auto dimsVec = dims.vec();
42	    int64_t totalLength = 1;
43	    for (size_t i = 0; i < dimsVec.size(); ++i) {
44	        totalLength *= dimsVec[i];
45	    }
46	
47	    // ---- 创建输出张量 ----
48	    at::Tensor output = at::empty(dimsVec, value.options());
49	
50	    if (totalLength == 0) {
51	        return output;
52	    }
53	
54	    int64_t dtypeSize = value.element_size();
55	    auto scalarType = value.scalar_type();
56	
57	    // ---- dtypeFlag 映射 ----
58	    // 0=float16, 1=float32, 2=bfloat16, 3=int8, 4=int32, 5=int64, 6=bool
59	    int64_t dtypeFlag = 0;
60	    float scalarFloat = 0.0f;
61	    int64_t scalarInt = 0;
62	
63	    if (scalarType == at::kHalf) {
64	        dtypeFlag = 0;
65	        scalarFloat = static_cast<float>(value.item<at::Half>());
66	    } else if (scalarType == at::kFloat) {
67	        dtypeFlag = 1;
68	        scalarFloat = value.item<float>();
69	    } else if (scalarType == at::kBFloat16) {
70	        dtypeFlag = 2;
71	        scalarFloat = static_cast<float>(value.item<at::BFloat16>());
72	    } else if (scalarType == at::kChar) {
73	        dtypeFlag = 3;
74	        scalarInt = static_cast<int64_t>(value.item<int8_t>());
75	    } else if (scalarType == at::kInt) {
76	        dtypeFlag = 4;
77	        scalarInt = static_cast<int64_t>(value.item<int32_t>());
78	    } else if (scalarType == at::kLong) {
79	        dtypeFlag = 5;
80	        scalarInt = value.item<int64_t>();
81	    } else if (scalarType == at::kBool) {
82	        dtypeFlag = 6;
83	        scalarInt = value.item<bool>() ? 1 : 0;
84	    }
85	
86	    // ---- 获取硬件参数 ----
87	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
88	    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
89	    uint64_t ubSize;
90	    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
91	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
92	
93	    // ---- Effective dtype size (kernel may use wider internal types) ----
94	    int64_t effectiveDtypeSize = dtypeSize;
95	    if (dtypeFlag == 3 || dtypeFlag == 6) {
96	        effectiveDtypeSize = 2;  // int8/bool: kernel uses int16_t
97	    } else if (dtypeFlag == 5) {
98	        effectiveDtypeSize = 4;  // int64: kernel uses int32_t (with TBuf)
99	    }
100	    // int64 kernel (Fill64): TBuf(cap=2*tileLength int32) + TQue(2x, cap=2*tileLength int32)
101	    //   = 1 * (2*4) + 2 * (2*4) = 8 + 16 = 24 bytes per int64 element
102	    int64_t bufferCoefficient;
103	    if (dtypeFlag == 5) {
104	        bufferCoefficient = 32; // int64: TBuf(8) + TQue*2(16) = 24, add safety margin -> 32
105	    } else {
106	        bufferCoefficient = 3 * effectiveDtypeSize; // fp16/bf16: 6, fp32/int32: 12, int8: 6
107	    }
108	    // ---- Block 级 tiling (核间切分, Cache Line 512B 对齐) ----
109	    // Use byte-level alignment, then convert to elements
110	    int64_t totalLenBytes = totalLength * dtypeSize;
111	    int64_t coreNumClamped = coreNum < 1 ? 1 : coreNum;
112	    int64_t bytesPerCore = (totalLenBytes + coreNumClamped - 1) / coreNumClamped;
113	    int64_t bytesPerCoreAligned = ((bytesPerCore + CACHE_LINE_BYTE_LENGTH - 1) / CACHE_LINE_BYTE_LENGTH) * CACHE_LINE_BYTE_LENGTH;
114	
115	    int64_t usedCoreNum = (totalLenBytes + bytesPerCoreAligned - 1) / bytesPerCoreAligned;
116	    if (usedCoreNum < 1) { usedCoreNum = 1; }
117	    int64_t formerNum = usedCoreNum - 1;
118	    int64_t formerLength = bytesPerCoreAligned / dtypeSize;
119	    int64_t tailLengthBytes = totalLenBytes - (usedCoreNum - 1) * bytesPerCoreAligned;
120	    int64_t tailLength = tailLengthBytes / dtypeSize;
121	
122	    // ---- UB 级 tiling (核内切分) ----
123	    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
124	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
125	    // alignElements: ensure 32B in UB for the internal type; use the larger of 32/dtypeSize and 32/effectiveDtypeSize
126	    int64_t alignElements = 32 / dtypeSize;
127	    int64_t alignElementsEff = 32 / effectiveDtypeSize;
128	    if (alignElementsEff > alignElements) { alignElements = alignElementsEff; }
129	    if (alignElements < 1) { alignElements = 1; }
130	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
131	
132	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
133	
134	    // All params must be left-values for EXEC_KERNEL_CMD
135	    EXEC_KERNEL_CMD(fill, blockDim,
136	                    output,
137	                    formerNum, formerLength, tailLength, tileLength,
138	                    scalarFloat, scalarInt, dtypeFlag);
139	
140	    return output;
141	}
142	
143	}  // namespace ascend_kernel
