// Fill op_host — tiling calculation + EXEC_KERNEL_CMD launch
// Scalar broadcast fill: output[i] = scalarValue for all i

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_fill.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

at::Tensor fill(at::IntArrayRef dims, const at::Tensor &value)
{
    // ---- 输入校验 ----
    TORCH_CHECK(value.dim() == 0, "fill: value must be a 0-dim scalar tensor, got ", value.dim(), " dims");
    TORCH_CHECK(
        value.scalar_type() == at::kFloat || value.scalar_type() == at::kHalf ||
            value.scalar_type() == at::kBFloat16 || value.scalar_type() == at::kChar ||
            value.scalar_type() == at::kInt || value.scalar_type() == at::kLong ||
            value.scalar_type() == at::kBool,
        "fill: supported dtypes: float32, float16, bfloat16, int8, int32, int64, bool; got ",
        value.scalar_type());

    auto dimsVec = dims.vec();
    int64_t totalLength = 1;
    for (size_t i = 0; i < dimsVec.size(); ++i) {
        totalLength *= dimsVec[i];
    }

    // ---- 创建输出张量 ----
    at::Tensor output = at::empty(dimsVec, value.options());

    if (totalLength == 0) {
        return output;
    }

    int64_t dtypeSize = value.element_size();
    auto scalarType = value.scalar_type();

    // ---- dtypeFlag 映射 ----
    // 0=float16, 1=float32, 2=bfloat16, 3=int8, 4=int32, 5=int64, 6=bool
    int64_t dtypeFlag = 0;
    float scalarFloat = 0.0f;
    int64_t scalarInt = 0;

    if (scalarType == at::kHalf) {
        dtypeFlag = 0;
        scalarFloat = static_cast<float>(value.item<at::Half>());
    } else if (scalarType == at::kFloat) {
        dtypeFlag = 1;
        scalarFloat = value.item<float>();
    } else if (scalarType == at::kBFloat16) {
        dtypeFlag = 2;
        scalarFloat = static_cast<float>(value.item<at::BFloat16>());
    } else if (scalarType == at::kChar) {
        dtypeFlag = 3;
        scalarInt = static_cast<int64_t>(value.item<int8_t>());
    } else if (scalarType == at::kInt) {
        dtypeFlag = 4;
        scalarInt = static_cast<int64_t>(value.item<int32_t>());
    } else if (scalarType == at::kLong) {
        dtypeFlag = 5;
        scalarInt = value.item<int64_t>();
    } else if (scalarType == at::kBool) {
        dtypeFlag = 6;
        scalarInt = value.item<bool>() ? 1 : 0;
    }

    // ---- 获取硬件参数 ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Effective dtype size (kernel may use wider internal types) ----
    int64_t effectiveDtypeSize = dtypeSize;
    if (dtypeFlag == 3 || dtypeFlag == 6) {
        effectiveDtypeSize = 2;  // int8/bool: kernel uses int16_t
    } else if (dtypeFlag == 5) {
        effectiveDtypeSize = 4;  // int64: kernel uses int32_t
    }
    // int64 (Fill64): TBuf(cap=2*tl) + TQue(2x,cap=2*tl) = tl*24 bytes per int64 elem
    int64_t bufferCoefficient;
    if (dtypeFlag == 5) {
        bufferCoefficient = 48; // int64: UB=tl*24, safety margin -> coefficient=48
    } else {
        bufferCoefficient = 3 * effectiveDtypeSize; // fp16/bf16: 6, fp32/int32: 12, int8: 6
    }
    // ---- Block 级 tiling (核间切分, Cache Line 512B 对齐) ----
    // Use byte-level alignment, then convert to elements
    int64_t totalLenBytes = totalLength * dtypeSize;
    int64_t coreNumClamped = coreNum < 1 ? 1 : coreNum;
    int64_t bytesPerCore = (totalLenBytes + coreNumClamped - 1) / coreNumClamped;
    int64_t bytesPerCoreAligned = ((bytesPerCore + CACHE_LINE_BYTE_LENGTH - 1) / CACHE_LINE_BYTE_LENGTH) * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLenBytes + bytesPerCoreAligned - 1) / bytesPerCoreAligned;
    if (usedCoreNum < 1) { usedCoreNum = 1; }
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = bytesPerCoreAligned / dtypeSize;
    int64_t tailLengthBytes = totalLenBytes - (usedCoreNum - 1) * bytesPerCoreAligned;
    int64_t tailLength = tailLengthBytes / dtypeSize;

    // ---- UB 级 tiling (核内切分) ----
    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    // alignElements: ensure 32B in UB for the internal type; use the larger of 32/dtypeSize and 32/effectiveDtypeSize
    int64_t alignElements = 32 / dtypeSize;
    int64_t alignElementsEff = 32 / effectiveDtypeSize;
    if (alignElementsEff > alignElements) { alignElements = alignElementsEff; }
    if (alignElements < 1) { alignElements = 1; }
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // All params must be left-values for EXEC_KERNEL_CMD
    EXEC_KERNEL_CMD(fill, blockDim,
                    output,
                    formerNum, formerLength, tailLength, tileLength,
                    scalarFloat, scalarInt, dtypeFlag);

    return output;
}

}  // namespace ascend_kernel
