13	static __aicore__ void FillNative(GM_ADDR output,
14	                                   int64_t formerNum, int64_t formerLength,
15	                                   int64_t tailLength, int64_t tileLength,
16	                                   T val)
17	{
18	    AscendC::TPipe pipe;
19	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> q;
20	    AscendC::GlobalTensor<T> gm;
21	
22	    int64_t blk = AscendC::GetBlockIdx();
23	    int64_t len;
24	    if (blk < formerNum) { len = formerLength; gm.SetGlobalBuffer((__gm__ T *)output + formerLength * blk, len); }
25	    else { len = tailLength; int64_t ti = blk - formerNum; gm.SetGlobalBuffer((__gm__ T *)output + formerLength * formerNum + tailLength * ti, len); }
26	
27	    pipe.InitBuffer(q, BUFFER_NUM, tileLength * sizeof(T));
28	
29	    int64_t tn = (len + tileLength - 1) / tileLength;
30	    int64_t tt = len - (tn - 1) * tileLength;
31	    int64_t an = 32 / (int64_t)sizeof(T);
32	    int64_t at = ((tt + an - 1) / an) * an;
33	
34	    for (int64_t i = 0; i < tn - 1; ++i) {
35	        AscendC::LocalTensor<T> ol = q.AllocTensor<T>();
36	        AscendC::Duplicate(ol, val, tileLength);
37	        q.EnQue<T>(ol);
38	        AscendC::LocalTensor<T> o2 = q.DeQue<T>();
39	        AscendC::DataCopyExtParams cp {1, (uint32_t)(tileLength * sizeof(T)), 0, 0, 0};
40	        AscendC::DataCopyPad(gm[i * tileLength], o2, cp);
41	        q.FreeTensor(o2);
42	    }
43	    if (tn > 0) {
44	        AscendC::LocalTensor<T> ol = q.AllocTensor<T>();
45	        AscendC::Duplicate(ol, val, at);
46	        q.EnQue<T>(ol);
47	        AscendC::LocalTensor<T> o2 = q.DeQue<T>();
48	        AscendC::DataCopyExtParams cp {1, (uint32_t)(tt * sizeof(T)), 0, 0, 0};
49	        AscendC::DataCopyPad(gm[(tn - 1) * tileLength], o2, cp);
50	        q.FreeTensor(o2);
51	    }
